def transform(grid):
    """Expand the single 2 into diagonal wavefronts; mark every fourth
    diagonal inside the wavefront with 1."""
    if not grid or len(grid) != 1:
        raise ValueError("expected a single-row input")
    n = len(grid[0])
    peaks = [i for i, value in enumerate(grid[0]) if value == 2]
    if len(peaks) != 1:
        raise ValueError("expected exactly one 2")
    center = peaks[0]
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if abs(c - center) == r:
                out[r][c] = 2
            elif abs(c - center) <= r and (c - r - center) % 4 == 0:
                out[r][c] = 1
    return out
